    region_ratio = region_ratio.sort_values('ratio', ascending=False)
    result['segments'].append({
        "segment_column": "region",
        "metric_column": "claim_amount",
        "aggregation": "ratio",
        "label": "share_of_total_claim_amount",
        "results": [{"name": str(row['region']), "value": float(row['ratio'])} for _, row in region_ratio.iterrows()]
    })
except Exception:
    pass

try:
