    })
except Exception:
    pass

try:
    from scipy import stats as _stats
    regions = df['region'].dropna().unique()
    groups = [df[df['region'] == r]['claim_amount'].dropna().values for r in regions]
    if len(groups) >= 2:
        stat, p = _stats.kruskal(*groups)
        stat = float(stat)
        p = float(p)
        interp = f"Kruskal-Wallis H={stat:.3f}, p={p:.3g}; " + ("significant difference in claim_amount across regions" if p < 0.05 else "no significant difference in claim_amount across regions")
        result['statistical_tests'].append({
            "test_name": "Kruskal-Wallis (claim_amount by region)",
            "statistic": stat,
            "p_value": p,
            "interpretation": interp
        })
except Exception:
    pass

try:
    result['assumptions'].append("claim_amount aggregated as sum per region for total; mean per region for average comparison")
    result['assumptions'].append("Kruskal-Wallis used (non-parametric) due to zero-inflated claim_amount distribution")
    result['assumptions'].append("Share of total computed as region sum / dataset total claim_amount")
except Exception:
    pass

